// src/app/messages/[userId]/page.jsx
"use client";

import { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { useAuth } from "@/contexts/AuthContext";
import { useSocket } from "@/contexts/SocketContext";
import api from "@/services/api";
import { VideoIcon } from "lucide-react";

export default function ChatPage() {
  const { userId } = useParams();
  const router = useRouter();
  const socket = useSocket();
  const { user } = useAuth();

  const [receiver, setReceiver] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [incomingCall, setIncomingCall] = useState(null);

  useEffect(() => {
    if (!userId || !socket || !user) return;

    async function fetchReceiver() {
      const res = await api.get(`/api/users/profile/${userId}`);
      setReceiver(res.data.user);
    }

    async function fetchMessages() {
      const res = await api.get(`/api/messages/${userId}`);
      setMessages(res.data);
    }

    fetchReceiver();
    fetchMessages();

    socket.emit("join", user.id);

    socket.on("receive_message", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    socket.on("incoming_call", (data) => {
      setIncomingCall(data);
    });

    return () => {
      socket.off("receive_message");
      socket.off("incoming_call");
    };
  }, [socket, user, userId]);

  const sendMessage = async () => {
    if (!content.trim()) return;
    socket.emit("send_message", {
      receiver_id: userId,
      content,
    });
    setContent("");
  };

  const triggerCall = () => {
    socket.emit("start_call", {
      from: user.id,
      to: userId,
      name: user.username,
      avatar: user.avatar,
    });
  };

  const acceptCall = () => {
    alert("Accepted call from " + incomingCall.name);
    setIncomingCall(null);
  };

  const declineCall = () => {
    alert("Declined call");
    setIncomingCall(null);
  };

  return (
    <div className="flex flex-col h-screen">
      {/* Header */}
      <div className="flex items-center justify-between bg-gray-900 text-white px-4 py-2 shadow">
        <div className="flex items-center gap-3">
          <button onClick={() => router.back()}>&larr;</button>
          <img
            src={receiver?.avatar}
            className="w-10 h-10 rounded-full object-cover"
            alt={receiver?.username}
          />
          <h2 className="text-lg font-semibold">{receiver?.username}</h2>
        </div>

        <button
          onClick={triggerCall}
          className="flex items-center gap-1 bg-green-600 hover:bg-green-700 text-white px-3 py-1 rounded-md"
        >
          <VideoIcon size={18} /> Call
        </button>
      </div>

      {/* Message List */}
      <div className="flex-1 p-4 overflow-y-auto bg-gray-900">
        {messages.map((msg, i) => (
          <div
            key={i}
            className={`mb-2 flex ${
              msg.sender_id === user.id ? "justify-end" : "justify-start"
            }`}
          >
            <div className="bg-blue-500 text-white px-4 py-2 rounded-lg max-w-xs">
              {msg.content}
            </div>
          </div>
        ))}
      </div>

      {/* Input Box */}
      <div className="flex items-center border-t border-gray-700 p-3 bg-gray-900">
        <input
          value={content}
          onChange={(e) => setContent(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && sendMessage()}
          placeholder="Type a message..."
          className="flex-1 bg-gray-800 text-white px-4 py-2 rounded mr-2"
        />
        <button
          onClick={sendMessage}
          className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded"
        >
          Send
        </button>
      </div>

      {/* Incoming Call Popup */}
      {incomingCall && (
        <div className="absolute inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-xl shadow-lg text-center">
            <p className="text-lg font-semibold mb-2">
              Incoming call from {incomingCall.name}
            </p>
            <div className="flex justify-center gap-4 mt-4">
              <button
                onClick={acceptCall}
                className="bg-green-500 hover:bg-green-600 text-white px-4 py-2 rounded"
              >
                Accept
              </button>
              <button
                onClick={declineCall}
                className="bg-red-500 hover:bg-red-600 text-white px-4 py-2 rounded"
              >
                Decline
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
